-- An original post's media decision is inspectable independently of its prompt.
ALTER TABLE trace_events DROP CONSTRAINT IF EXISTS trace_events_type_check;
ALTER TABLE trace_events ADD CONSTRAINT trace_events_type_check
  CHECK (type IN ('JOB_CREATED', 'JOB_CLAIMED', 'CONTEXT_RESOLVED', 'MEMORY_SELECTED', 'PROMPT_ASSEMBLED', 'MODEL_REQUEST_STARTED', 'MODEL_REQUEST_COMPLETED', 'MODEL_REQUEST_FAILED', 'VALIDATION_PASSED', 'VALIDATION_FAILED', 'APPROVAL_REQUESTED', 'APPROVAL_DECIDED', 'ACTION_STARTED', 'TARGET_VERIFIED', 'TARGET_VERIFICATION_FAILED', 'ACTION_COMPLETED', 'ACTION_FAILED', 'ACTION_SKIPPED_DUPLICATE', 'DRY_RUN_STOPPED', 'MEMORY_WRITTEN', 'JOB_RETRY_SCHEDULED', 'JOB_FAILED_PERMANENT', 'JOB_RECOVERED', 'JOB_CANCELLED', 'DIAGNOSTIC_CAPTURED', 'MEDIA_RESOLVED', 'POST_MEDIA_DECIDED', 'RELATIONSHIP_LOADED', 'STANCE_SELECTED', 'STANCE_CONFLICT', 'STANCE_REVISED', 'ENGAGEMENT_DECIDED', 'INTENT_SELECTED', 'VOICE_COMPILED', 'QUALITY_SCORED', 'REPETITION_DETECTED', 'RESEARCH_DONE', 'ACTION_BLOCKED', 'CAPABILITY_USED', 'CAPABILITY_OFFERED'));
